module Top;
 typedef enum logic [127:0] {ZERO = 128'd0, HIGH = 128'h80000000000000000000000000000000} E;
 E e;
 initial begin
  e = HIGH;
  $display("[%s %0d]", e.name(), e == HIGH);
  e = ZERO;
  $display("[%0d %s]", $cast(e, 128'h80000000000000000000000000000000), e.name());
 end
endmodule
